"""Figure for notes 21.76-21.77: error by hour of the target day, market model with Timestral on the shift (A), Timestral on the price (P), and their average."""
import numpy as np, matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
SP = "/tmp/claude-0/-home-user-EpexPredictor/d6125cc0-c431-5b93-a06f-0110cd871ab6/scratchpad"; BLUE, ORANGE, AQUA, YEL, INK, MUTED, SURF, GRID, NEUT = "#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#0b0b0b", "#52514e", "#fcfcfb", "#e9e8e3", "#a8a79f"
plt.rcParams.update({"font.size": 9, "axes.edgecolor": "#c9c8c2", "axes.labelcolor": MUTED, "xtick.color": MUTED, "ytick.color": MUTED, "figure.facecolor": SURF, "axes.facecolor": SURF, "savefig.facecolor": SURF, "font.family": "DejaVu Sans"})
Z = np.load(f"{SP}/out/day_look.npz"); PER = (("winter", "Winter, used (30 days)"), ("summer", "Summer, used (50)"), ("autumn", "Autumn, used (66)"), ("winterf", "Winter, fresh (30)"), ("summerf", "Summer, fresh (50)")); fig, axs = plt.subplots(2, 5, figsize=(21, 7.6), gridspec_kw=dict(wspace=0.22, hspace=0.42, height_ratios=[1, 0.8])); h = np.arange(24) + 0.5; rng = np.random.default_rng(0)
for i, (p, lab) in enumerate(PER):
    a, A, P = (Z[f"{p}_{k}"].astype(float) for k in ("a", "A", "P")); B = 0.5 * (A + P); hr = lambda e: np.abs(e).reshape(len(a), 24, 4).mean((0, 2)); ax = axs[0, i]
    for v, col, nm, lw in ((P, ORANGE, "Timestral on the price", 1.8), (A, BLUE, "market model, Timestral on the shift", 1.8), (B, AQUA, "average of the two", 2.2)): ax.plot(h, hr(v - a), color=col, linewidth=lw, label=nm)
    ax.axvspan(0, 6, color=GRID, alpha=0.6, linewidth=0); ax.set_xlim(0, 24); ax.set_ylim(0, None); ax.set_xticks([0, 6, 12, 18, 24]); ax.grid(True, color=GRID, linewidth=0.6); ax.set_axisbelow(True); [ax.spines[s].set_visible(False) for s in ("top", "right")]; ax.set_xlabel("hour of the target day")
    if i == 0: ax.set_ylabel("mean absolute error, ct/kWh"); ax.legend(frameon=False, loc="lower right", fontsize=7.5)
    eA, eP, eB = (np.abs(v - a).mean(1) for v in (A, P, B)); ax.set_title(f"{lab}\nwhole day: A {eA.mean():.2f}, P {eP.mean():.2f}, average {eB.mean():.2f}", loc="left", fontsize=9.5, fontweight="bold", color=INK)
    ax = axs[1, i]; blk = 7 if p == "autumn" else 3; nb = len(a) // blk; dh = (np.abs(B - a) - np.abs(P - a)).reshape(len(a), 24, 4).mean(2); m = dh.mean(0); bs = np.array([dh[:nb * blk].reshape(nb, blk, 24).mean(1)[rng.integers(0, nb, nb)].mean(0) for _ in range(2000)]); lo, hi = np.percentile(bs, [5, 95], 0)
    ax.fill_between(h, lo, hi, color=AQUA, alpha=0.25, linewidth=0); ax.plot(h, m, color=AQUA, linewidth=2); ax.axhline(0, color=INK, linewidth=0.7); ax.axvspan(0, 6, color=GRID, alpha=0.6, linewidth=0); ax.set_xlim(0, 24); ax.set_xticks([0, 6, 12, 18, 24]); ax.grid(True, color=GRID, linewidth=0.6); ax.set_axisbelow(True); [ax.spines[s].set_visible(False) for s in ("top", "right")]; ax.set_xlabel("hour of the target day")
    if i == 0: ax.set_ylabel("average minus Timestral on the price, ct/kWh\n(band: 5-95% block bootstrap)")
    d = eB - eP; x = d[:nb * blk].reshape(nb, blk).mean(1); b = np.percentile([x[rng.integers(0, nb, nb)].mean() for _ in range(4000)], [5, 95]); ax.set_title(f"Average minus price route, whole day:\n{d.mean():+.2f} ({b[0]:+.2f} .. {b[1]:+.2f})", loc="left", fontsize=9, fontweight="bold", color=INK)
fig.suptitle("The whole target day, forecast at midnight the day before: by day the two routes differ; their average is ahead of the price route in three sets, at zero in one and not in autumn (night shaded; fresh sets post hoc)", x=0.06, ha="left", fontsize=11, fontweight="bold", color=INK, y=0.99); fig.savefig(f"{SP}/out/day_look.png", dpi=95, bbox_inches="tight"); print("ok")
a, A, P = (Z[f"summerf_{k}"].astype(float) for k in ("a", "A", "P")); eA = np.abs(A - a)[:, 40:64].mean(1); eP = np.abs(P - a)[:, 40:64].mean(1); o = np.argsort(eP - eA)[-5:]; print("summer fresh, midday: median error A", round(float(np.median(eA)), 2), "P", round(float(np.median(eP)), 2), "| five days where P is worst relative to A: P", np.round(eP[o], 1), "A", np.round(eA[o], 1), "actual midday mean", np.round(a[o, 40:64].mean(1), 1), "P forecast", np.round(P[o, 40:64].mean(1), 1), "A forecast", np.round(A[o, 40:64].mean(1), 1)); d = (eA - eP); print("   A - P midday without those five:", round(float(np.delete(d, o).mean()), 2), "| share of days A better:", round(float((d < 0).mean()), 2))
a, A, P = (Z[f"autumn_{k}"].astype(float) for k in ("a", "A", "P")); eA = np.abs(A - a)[:, 40:64].mean(1); eP = np.abs(P - a)[:, 40:64].mean(1); o = np.argsort(eA - eP)[-5:]; print("autumn, midday: five days where A is worst relative to P: A", np.round(eA[o], 1), "P", np.round(eP[o], 1), "actual", np.round(a[o, 40:64].mean(1), 1), "A forecast", np.round(A[o, 40:64].mean(1), 1), "P forecast", np.round(P[o, 40:64].mean(1), 1), "| without them A - P:", round(float(np.delete(eA - eP, o).mean()), 2), "| share of days A worse:", round(float((eA > eP).mean()), 2))
